#include <sys/sysinfo.h>
#include <stdio.h>
int main(void) { struct sysinfo s; if(sysinfo(&s)) return 1; printf("{\"totalram\":%lu,\"freeram\":%lu,\"sharedram\":%lu,\"bufferram\":%lu,\"totalswap\":%lu,\"freeswap\":%lu,\"mem_unit\":%u}\n",s.totalram,s.freeram,s.sharedram,s.bufferram,s.totalswap,s.freeswap,s.mem_unit); return 0; }
